"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["89661"],{1569(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.cascata_fallback_nao_selecionado_na_oferta","status":422,"titulo":"O fallback (ou o destino resolv\xedvel) da cascata n\xe3o \xe9 modalidade selecionada na oferta"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.cascata_fallback_nao_selecionado_na_oferta","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["A cascata do processo \xe9 \xfanica, mas cada oferta de curso seleciona seu\\npr\xf3prio subconjunto de modalidades \u2014 a fila de destinos de uma origem e o\\nfallback s\xf3 resolvem, numa oferta espec\xedfica, se pelo menos uma das\\nmodalidades que a cascata cita ali estiver de fato selecionada. Esta causa\\ncobre dois cen\xe1rios:","- O **fallback** da cascata n\xe3o \xe9 modalidade selecionada na oferta \u2014 sem\\n  ele, uma vaga que percorresse toda a fila de qualquer origem sem\\n  preenchimento n\xe3o teria onde parar.\\n- **Nenhum destino da fila de uma origem** \xe9 modalidade selecionada na\\n  oferta \u2014 a fila entera \xe9 resolvida contra as modalidades daquela oferta\\n  espec\xedfica, e se nenhuma posi\xe7\xe3o resolver, o remanejamento tamb\xe9m n\xe3o\\n  tem para onde ir.","O primeiro cen\xe1rio \xe9 conferido uma vez por oferta (depois de confirmar que\\no processo tem cascata \u2014 ver\\n[`cascata_origem_ausente`](/erros/uniplus.selecao.processo_seletivo.cascata_origem_ausente));\\no segundo \xe9 conferido para cada modalidade `SEGUE_ORDEM_DE_REMANEJAMENTO` da oferta, em\\nordem determin\xedstica. Sequencial: a primeira oferta ou modalidade com essa\\ninconsist\xeancia interrompe a avalia\xe7\xe3o; nunca acumula com nenhuma outra\\ncausa desta s\xe9rie."],"comoResolver":["Se o erro aponta o fallback, confirme que a modalidade de fallback da\\ncascata est\xe1 selecionada na oferta indicada. Se aponta uma origem, revise\\na fila de destinos dela na cascata \u2014 pelo menos um dos c\xf3digos precisa\\ncorresponder a uma modalidade selecionada naquela oferta."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);